#### Folder selector

- **action**: `folder-selector-modal-open`
- **args type**:

  ```typescript
  {
      initialSelectedFolders?: Array<{ id: number; name: string }>;
      // Whether to show all assets
      allMaterials?: boolean;
  }
  ```
- **result.data type**:

  ```typescript
  {
      selectedFolders: Array<{ id: number; name: string }>;
      allMaterials: boolean;
  }
  ```
- **Example**:

  ```typescript
  // Request
  {
      action: "folder-selector-modal-open",
      args: {
          initialSelectedFolders: [{ id: 123, name: 'Design assets' }],
          allMaterials: false
      }
  }

  // Successful response
  {
      result: {
          success: true,
          data: {
              selectedFolders: [
                  { id: 123, name: 'Design assets' },
                  { id: 456, name: 'Product images' }
              ],
              allMaterials: false
          }
      }
  }

  // Cancellation response
  {
      result: {
          success: false,
          code: "cancelled",
          message: "Operation canceled by user"
      }
  }
  ```

#### Member and department selector

- **action**: `member-selector-modal-open`
- **args type**:

  ```typescript
  {
      selectedItems?: {
          members?: Array<{ id: string; name: string }>;
          departments?: Array<{ id: string; name: string }>;
          groups?: Array<{ id: string; name: string }>;
      };
  }
  ```
- **result.data type**:

  ```typescript
  {
      members: Array<{ id: string; name: string;departmentsName?:string;avatarUrl?:string }>;
      departments: Array<{ id: string; name: string }>;
      groups: Array<{ id: string; name: string }>;
  }
  ```
- **Example**:

  ```typescript
  // Request
  {
      action: "member-selector-modal-open",
      args: {
          // Selected items
          selectedItems: {
              members: [{ id: "user_123", name: "Alex", departmentsName:"Muse, Design", avatarUrl:"https://"}],
              departments: [{ id: "dept_001", name: "Design" }]
          }
      }
  }

  // Successful response
  {
      result: {
          success: true,
          data: {
              members: [
                  { id: "user_123", name: "Alex" },
                  { id: "user_456", name: "Sam" }
              ],
              departments: [{ id: "dept_001", name: "Design" }],
              groups: []
          }
      }
  }

  // Cancellation response
  {
      result: {
          success: false,
          code: "cancelled",
          message: "Operation canceled by user"
      }
  }
  ```

#### Asset selector

- **action**: `assets-selector-modal-open`
- **args type**:

  ```typescript
  enum EAssetType {
      image = 'image',           // Images
      video = 'video',           // Videos
      audio = 'audio',           // Audio
      js = 'js',                 // Design source files
      document = 'document',     // Text documents
      PDocument = 'PDocument',   // Presentations
      excel = 'excel',           // Spreadsheets
      font = 'font',             // Fonts
      zip = 'zip',               // Archives
      dll = 'dll',               // Applications
      code = 'code',             // Code
      model = 'model',           // Models
      triD = 'triD',             // 3D
      url = 'url',               // Webpages
      unknown = 'unknown',       // Unknown files
  }
  {
    initialSelectedAssetIds?: number[];
    /**
     * Allowed asset types. Omit to allow all types.
     * Values follow the asset type field: image, video, audio, js, document, PDocument, excel, font, zip, dll, code, model, triD, url.
     */
    allowedTypes?: EAssetType[];
    /**
     * Per-type quantity limits. When provided, only listed types are selectable; omit limit for unlimited items of that type.
     * When used with allowedTypes, allowedTypes is the allowlist and dataLimit only adds quantity limits.
     */
    dataLimit?: Array<{
      type: EAssetType;
      limit?: number;
    }>;
    /**
     * Initial list filters, matching the homepage filter bar. Users can still change filters in the selector.
     */
    filters?: {
      types?: EAssetType[];
      extensions?: string[];
      size?: {
        min?: number;
        max?: number;
        unit?: 'KB' | 'MB' | 'GB';
      };
      dimension?: {
        minWidth?: number;
        maxWidth?: number;
        minHeight?: number;
        maxHeight?: number;
      };
    };
  }
  ```
- **result.data type**:

  ```typescript

  {
      selectedAssets: IAssetLite[];
  }
  ```
- **Example**:

  ```typescript
  // Request
  {
      action: "assets-selector-modal-open",
      args: {
          initialSelectedAssetIds: [123, 456],
          allowedTypes: ['image'],
          filters: {
              types: ['image'],
              size: { min: 100, max: 10240, unit: 'KB' },
              dimension: { minWidth: 512, minHeight: 512 },
          },
      }
  }

  // Successful response
  {
      result: {
          success: true,
          data: {
              selectedAssets: [
                  { id: 123, name: 'logo.png', type: 'image' },
                  { id: 456, name: 'banner.png', type: 'image' }
              ]
          }
      }
  }

  // Cancellation response
  {
      result: {
          success: false,
          code: "cancelled",
          message: "Operation canceled by user"
      }
  }
  ```

#### Navigate to a page

- **action**: `goto`
- **args type**:

  ```typescript
  {
    url: string;
  }
  ```
- **Description**: The parent app navigates when it receives this message. No response is required.
- **Example**:

  ```typescript
  // Request
  {
      action: "goto",
      args: {
          url: "https://example.com/target-page",
          target:"_blank"
      }
  }
  ```

#### Synchronize paths

- **action**: `syncPath`
- **args type**:

  ```typescript
  {
    path: string;
  }
  ```
- **Description**: The parent app updates the current page's hash path. No response is required. This synchronizes iframe routing state with the parent window URL.
- **Example**:

  ```typescript
  // Request
  {
      action: "syncPath",
      args: {
          path: "#path=/tagging/settings"
      }
  }
  ```
